using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;
class QuotaLifecycleUiTests {
 static int checks,failures;static void Check(bool ok,string n){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(!ok)failures++;}
 static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var c in Tree(VisualTreeHelper.GetChild(o,i)))yield return c;}
 static void Pump(){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(150)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 static void Click(Window w,string text){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==text).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 static T Named<T>(DependencyObject w,string n)where T:DependencyObject{return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}
 [STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var folder=Path.Combine(args[0],"ui-data-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);Environment.SetEnvironmentVariable("CONAN_PET_TEST_MODE","1");var runtime=new AssistantRuntime(folder);runtime.Config.Monitor.Quota.Enabled=false;var skills=new SkillRuntime(folder);var extra=new AdvancedRuntime(folder);var w=new TerminalWindow(runtime,skills,extra,folder,x=>{},()=>{},x=>{},()=>"free");try{w.Width=1200;w.Height=850;w.Show();w.ShowPage("侦探备忘录");Pump();Click(w,"额度与重置");Check(Tree(w).OfType<CheckBox>().Any(c=>Convert.ToString(c.Content).Contains("后台查询官方额度")),"background query switch visible");var wake=Tree(w).OfType<CheckBox>().First(c=>Convert.ToString(c.Content).Contains("自动发送一次最小请求"));Check(wake.IsChecked==false,"wake switch defaults off in actual UI");wake.IsChecked=true;wake.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Check(runtime.Config.Monitor.Quota.Wake.Enabled,"wake switch saves choice");var inputMode=Named<ComboBox>(w,"到期时间填写方式");Check(inputMode.SelectedIndex==0,"new setup defaults to subscription-date calculation");inputMode.SelectedIndex=1;Pump();var date=Named<DatePicker>(w,"套餐到期日期");Check(!date.SelectedDate.HasValue,"expiry not invented from quota date");date.SelectedDate=new DateTime(2027,1,25);Named<TextBox>(w,"到期时间（24小时）").Text="18:30";Named<TextBox>(w,"提前提醒（天；0表示到期当天）预警点").Text="0,2,5,14";Click(w,"保存套餐到期提醒");Check(runtime.Config.Monitor.Quota.Subscription.ExpiresLocal=="2027-01-25T18:30","expiry picker and time persist exact local deadline");Check(runtime.Config.Monitor.Quota.Subscription.ReminderDays.SequenceEqual(new[]{0,2,5,14}),"custom reminder days saved from real editor");var saved=new JavaScriptSerializer().Deserialize<AssistantConfig>(File.ReadAllText(Path.Combine(folder,"assistant.json")));Check(saved.Monitor.Quota.Wake.Enabled&&saved.Monitor.Quota.Subscription.ExpiresLocal=="2027-01-25T18:30","restart data preserves independent choices");Check(Tree(w).OfType<Button>().Any(b=>Convert.ToString(b.Content).Contains("打开官方账户设置")),"official subscription settings entry present");
 inputMode.SelectedIndex=0;Pump();Named<DatePicker>(w,"套餐订阅日期").SelectedDate=new DateTime(2026,1,31);Named<TextBox>(w,"订阅时间（24小时）").Text="18:30";Pump();Check(date.SelectedDate==new DateTime(2026,2,28)&&Named<TextBox>(w,"到期时间（24小时）").Text=="18:30","subscription input updates expiry preview without manual calculation");Check(!date.IsEnabled&&Named<TextBox>(w,"到期时间（24小时）").IsReadOnly,"calculated date is read-only");var period=Named<ComboBox>(w,"订阅周期");period.SelectedIndex=3;Pump();Check(date.SelectedDate==new DateTime(2027,1,31),"changing subscription period recalculates preview");period.SelectedIndex=0;Click(w,"保存套餐到期提醒");var stored=new JavaScriptSerializer().Deserialize<AssistantConfig>(File.ReadAllText(Path.Combine(folder,"assistant.json")));Check(stored.Monitor.Quota.Subscription.FromSubscription&&stored.Monitor.Quota.Subscription.SubscribedLocal=="2026-01-31T18:30"&&stored.Monitor.Quota.Subscription.Deadline()==new DateTime(2026,2,28,18,30,0),"subscription date period and calculated deadline survive reload");
 period.SelectedIndex=1;Pump();Check(date.SelectedDate==new DateTime(2026,3,2),"thirty-day selection differs from calendar month in native preview");period.SelectedIndex=2;Named<TextBox>(w,"订阅天数").Text="45";Pump();Check(date.SelectedDate==new DateTime(2026,3,17),"custom day duration updates expiry live");Click(w,"保存套餐到期提醒");stored=new JavaScriptSerializer().Deserialize<AssistantConfig>(File.ReadAllText(Path.Combine(folder,"assistant.json")));Check(stored.Monitor.Quota.Subscription.DurationMode=="days"&&stored.Monitor.Quota.Subscription.SubscriptionDays==45,"day calculation mode survives restart");var sourceDate=Named<DatePicker>(w,"套餐订阅日期");sourceDate.IsDropDownOpen=true;Pump();Check(sourceDate.IsDropDownOpen&&((System.Windows.Controls.Primitives.Popup)sourceDate.Template.FindName("PART_Popup",sourceDate)).IsOpen&&((System.Windows.Controls.Primitives.Popup)sourceDate.Template.FindName("PART_Popup",sourceDate)).Child!=null,"new calendar button opens a real date picker popup");sourceDate.IsDropDownOpen=false;var clock=Named<TextBox>(w,"订阅时间（24小时）");clock.Select(0,2);clock.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,System.Windows.PresentationSource.FromVisual(clock),Environment.TickCount,System.Windows.Input.Key.Up){RoutedEvent=UIElement.PreviewKeyDownEvent});Check(clock.Text=="19:30","hour stepper changes actual time input");clock.Select(3,2);clock.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,System.Windows.PresentationSource.FromVisual(clock),Environment.TickCount,System.Windows.Input.Key.Down){RoutedEvent=UIElement.PreviewKeyDownEvent});Check(clock.Text=="19:29","minute stepper changes actual time input");
 var scroll=(ScrollViewer)typeof(TerminalWindow).GetField("pageScroll",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);scroll.ScrollToVerticalOffset(1710);Pump();var root=(FrameworkElement)w.Content;var image=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(root);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(image));using(var stream=File.Create(Path.Combine(args[0],"quota-lifecycle-settings.png")))enc.Save(stream);scroll.ScrollToBottom();Pump();Check(Math.Abs(scroll.VerticalOffset-scroll.ScrollableHeight)<1,"new settings sections remain scrollable to bottom");
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{w.Close();runtime.Telemetry.Dispose();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"quota-lifecycle-ui-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,real_settings_changed=false,model_request_sent=false}));return failures==0?0:1;}
}
